<?php
defined( 'ABSPATH' ) || exit;

final class EduFlow_Migration_Service {
	const STAGES=array('detect','dry_run','mapping','conflict_check','import','verification','retirement_report');
	const ORDER=array('teacher','student','admission','payment','access','batch','batch_student','class_teacher','demo_session','demo_booking','class','meet','user_link','attendance');
	const CONFLICTS=array('duplicate_mobile','duplicate_email','ambiguous_student','ambiguous_teacher','conflicting_payment','conflicting_access','conflicting_batch_membership','conflicting_class_schedule','conflicting_meet_url','duplicate_google_event_id','missing_parent_record','invalid_data','already_mapped_differently','source_changed');
	public static function register(){add_filter('eduflow_run_job_legacy_migration_batch',array(__CLASS__,'process_job'),10,2);}
	public static function stages(){return self::STAGES;} public static function is_valid_stage($stage){return in_array($stage,self::STAGES,true);}
	public static function definitions(){return (array)apply_filters('eduflow_legacy_adapter_definitions',array());}
	public static function adapters(){$out=array();foreach(self::definitions()as$definition){if(empty($definition['key'])||empty($definition['table'])||empty($definition['primary_key'])){continue;}$class='EduFlow_Legacy_'.str_replace(' ','_',ucwords(str_replace('_',' ',sanitize_key($definition['entity_type']??'')))).'_Adapter';if(!class_exists($class)){$class='EduFlow_Legacy_Table_Adapter';}$adapter=new $class($definition);$out[$adapter->key()]=$adapter;}return $out;}
	public static function detect(){global $wpdb;$configured=array();foreach(self::adapters()as$key=>$adapter){$configured[$key]=array('source_key'=>$key,'table'=>$adapter->source_table(),'entity_type'=>$adapter->entity_type(),'supported'=>true,'detected'=>$adapter->detect(),'record_count'=>$adapter->count());}$like_patterns=array('%ytc%','%batchflow%','%classflow%','%eduflow%');$unknown=array();foreach($like_patterns as$pattern){$tables=$wpdb->get_col($wpdb->prepare('SHOW TABLES LIKE %s',$pattern));foreach($tables as$table){if(0===strpos($table,$wpdb->prefix.'eduflow_')){continue;}$known=false;foreach($configured as$row){if($row['table']===$table){$known=true;break;}}if(!$known&&preg_match('/^[A-Za-z0-9_]+$/',$table)){$unknown[$table]=array('source_key'=>'manual:'.sanitize_key($table),'table'=>$table,'entity_type'=>'unsupported','supported'=>false,'detected'=>true,'record_count'=>null,'reason'=>'Schema not registered; manual adapter mapping required.');}}}return array_values(array_merge($configured,$unknown));}
	public static function fingerprint(array $normalized){ksort($normalized);return hash('sha256',wp_json_encode($normalized,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));}
	public static function reconcile($adapter,array $source,$institute_id){global $wpdb;$normalized=$adapter->normalize($source);$source_id=$adapter->source_id($source);$map=EduFlow_DB::table('migration_map');$mapped=$wpdb->get_row($wpdb->prepare("SELECT * FROM $map WHERE institute_id=%d AND legacy_source=%s AND legacy_table=%s AND legacy_id=%s",$institute_id,$adapter->key(),$adapter->source_table(),$source_id),ARRAY_A);$fingerprint=self::fingerprint($normalized);if($mapped){return array('decision'=>$mapped['source_fingerprint']===$fingerprint?'duplicate':'conflict','target_id'=>$mapped['target_db_id'],'reason'=>$mapped['source_fingerprint']===$fingerprint?'Already mapped and unchanged.':'Source changed after migration.','fingerprint'=>$fingerprint,'normalized'=>$normalized);}$errors=$adapter->validate($normalized);if($errors){return array('decision'=>'invalid','reason'=>implode(' ',$errors),'fingerprint'=>$fingerprint,'normalized'=>$normalized);}$entity=$adapter->entity_type();if(in_array($entity,array('student','teacher'),true)){return self::reconcile_person($entity,$normalized,$institute_id,$fingerprint);}$decision=apply_filters('eduflow_legacy_reconcile_'.$entity,null,$normalized,$institute_id,$adapter);return is_array($decision)?$decision:array('decision'=>'would_create','reason'=>'No existing source mapping; dependencies must validate during import.','fingerprint'=>$fingerprint,'normalized'=>$normalized);}
	private static function reconcile_person($entity,$row,$institute_id,$fingerprint){global $wpdb;$table=EduFlow_DB::table('student'===$entity?'students':'teachers');$matches=array();if(!empty($row['canonical_id'])){$id=$wpdb->get_col($wpdb->prepare("SELECT id FROM $table WHERE institute_id=%d AND canonical_id=%s",$institute_id,sanitize_text_field($row['canonical_id'])));$matches=array_merge($matches,$id);}if(!empty($row['mobile'])){$ids=$wpdb->get_col($wpdb->prepare("SELECT id FROM $table WHERE institute_id=%d AND mobile=%s",$institute_id,$row['mobile']));$matches=array_merge($matches,$ids);}if(!empty($row['email'])&&is_email($row['email'])){$ids=$wpdb->get_col($wpdb->prepare("SELECT id FROM $table WHERE institute_id=%d AND email=%s",$institute_id,$row['email']));$matches=array_merge($matches,$ids);}$matches=array_values(array_unique(array_map('absint',$matches)));if(count($matches)>1){return array('decision'=>'conflict','reason'=>'Multiple strong identity matches; name-only matching is prohibited.','fingerprint'=>$fingerprint,'normalized'=>$row);}if(1===count($matches)){return array('decision'=>'would_link','target_id'=>$matches[0],'reason'=>'One strong canonical/mobile/email match.','fingerprint'=>$fingerprint,'normalized'=>$row);}return array('decision'=>'would_create','reason'=>'No strong match; names are not used for automatic merging.','fingerprint'=>$fingerprint,'normalized'=>$row);}
	public static function start($source_key,$mode='dry_run',$entity_types=array(),$backup=false,$batch_size=100,$institute_id=0){global $wpdb;$mode=sanitize_key($mode);if(!in_array($mode,array('dry_run','selected','full_safe'),true)){return new WP_Error('invalid_migration_mode','Invalid migration mode.');}if('dry_run'!==$mode&&!$backup){return new WP_Error('backup_confirmation_required','Confirm a full files and database backup before a real import.');}$adapters=self::adapters();if(empty($adapters[$source_key])||!$adapters[$source_key]->detect()){return new WP_Error('legacy_source_unavailable','The configured legacy source is unavailable.');}$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();$now=current_time('mysql',true);$run_key=hash('sha256',$institute_id.'|'.$source_key.'|'.$mode.'|'.$now.'|'.get_current_user_id());$wpdb->insert(EduFlow_DB::table('migration_runs'),array('run_key'=>$run_key,'institute_id'=>$institute_id,'mode'=>$mode,'source_key'=>$source_key,'entity_types'=>implode(',',array_map('sanitize_key',$entity_types)),'batch_size'=>min(200,max(10,absint($batch_size))),'started_by'=>get_current_user_id(),'started_at'=>$now,'run_status'=>'pending','backup_confirmed'=>$backup?1:0,'status'=>'active','created_at'=>$now,'updated_at'=>$now));if(!$wpdb->insert_id){return new WP_Error('migration_run_failed','Migration run could not be created.');}$id=(int)$wpdb->insert_id;EduFlow_Audit_Service::log('migration_started','migration_run',$id,null,array('mode'=>$mode,'source'=>$source_key),$institute_id);self::queue($id,0);return $id;}
	private static function queue($run_id,$cursor){$key='migration:'.$run_id.':'.$cursor;return EduFlow_Job_Service::enqueue('legacy_migration_batch',array('run_id'=>$run_id,'cursor'=>$cursor),$key);}
	public static function process_job($unused,$payload){global $wpdb;$run_id=absint($payload['run_id']??0);$runs=EduFlow_DB::table('migration_runs');$run=$wpdb->get_row($wpdb->prepare("SELECT * FROM $runs WHERE id=%d AND run_status IN ('pending','running','failed')",$run_id),ARRAY_A);if(!$run){return true;}$adapters=self::adapters();$adapter=$adapters[$run['source_key']]??null;if(!$adapter||!$adapter->detect()){self::fail_run($run,'Legacy source is no longer readable.');return true;}$wpdb->update($runs,array('run_status'=>'running','updated_at'=>current_time('mysql',true)),array('id'=>$run_id,'institute_id'=>$run['institute_id']));$rows=$adapter->preview($run['cursor_value'],$run['batch_size']);$stats=array('processed'=>0,'created_count'=>0,'linked_count'=>0,'updated_count'=>0,'skipped_count'=>0,'duplicate_count'=>0,'conflict_count'=>0,'failed_count'=>0);foreach($rows as$row){$stats['processed']++;$decision=$adapter->reconcile($row,$run['institute_id']);$kind=$decision['decision'];if(in_array($kind,array('conflict','invalid'),true)){self::conflict($run,$adapter,$row,$decision);$stats['conflict_count']++;continue;}if('duplicate'===$kind){$stats['duplicate_count']++;continue;}if('dry_run'===$run['mode']){if('would_link'===$kind){$stats['linked_count']++;}elseif('would_create'===$kind){$stats['created_count']++;}else{$stats['skipped_count']++;}continue;}$result=self::import_locked($run,$adapter,$row,$decision);if(is_array($result)&&!empty($result['_migration_duplicate'])){$stats['duplicate_count']++;continue;}if(is_wp_error($result)){$stats['failed_count']++;self::conflict($run,$adapter,$row,array('decision'=>'invalid','reason'=>$result->get_error_message(),'fingerprint'=>$decision['fingerprint'],'normalized'=>$decision['normalized']));continue;}self::save_map($run,$adapter,$row,$decision,$result);$stats['created_count']++;}$next=(int)$run['cursor_value']+count($rows);$set=array('cursor_value'=>$next,'updated_at'=>current_time('mysql',true));foreach($stats as$key=>$value){$set[$key]=((int)$run[$key])+$value;}if(count($rows)<(int)$run['batch_size']){$set['run_status']='completed';$set['finished_at']=current_time('mysql',true);EduFlow_Audit_Service::log('dry_run'===$run['mode']?'migration_dry_run_performed':'migration_completed','migration_run',$run_id,null,$set,$run['institute_id']);}else{$set['run_status']='pending';self::queue($run_id,$next);}$wpdb->update($runs,$set,array('id'=>$run_id,'institute_id'=>$run['institute_id']));return true;}
	private static function import_locked($run,$adapter,$row,$decision){global $wpdb;$lock='eduflow_migration_'.hash('sha256',$run['institute_id'].'|'.$adapter->key().'|'.$adapter->source_table().'|'.$adapter->source_id($row));$acquired=(int)$wpdb->get_var($wpdb->prepare('SELECT GET_LOCK(%s,%d)',$lock,5));if(1!==$acquired){return new WP_Error('migration_record_locked','Another migration worker is processing this source record.');}try{$fresh=$adapter->reconcile($row,$run['institute_id']);if('duplicate'===($fresh['decision']??'')){return array('_migration_duplicate'=>true);}if(in_array($fresh['decision']??'',array('conflict','invalid'),true)){return new WP_Error('migration_reconciliation_changed',$fresh['reason']??'Reconciliation changed while waiting for a lock.');}return $adapter->import($row,$run['institute_id']);}finally{$wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',$lock));}}
	private static function save_map($run,$adapter,$row,$decision,$result){global $wpdb;$now=current_time('mysql',true);$target=is_array($result)?$result:array('id'=>$result);$wpdb->query($wpdb->prepare('INSERT INTO '.EduFlow_DB::table('migration_map').' (institute_id,legacy_source,legacy_table,legacy_id,new_entity,new_id,target_db_id,source_fingerprint,migration_status,migrated_at,created_at,updated_at) VALUES (%d,%s,%s,%s,%s,%s,%d,%s,%s,%s,%s,%s) ON DUPLICATE KEY UPDATE updated_at=VALUES(updated_at)',$run['institute_id'],$adapter->key(),$adapter->source_table(),$adapter->source_id($row),$adapter->entity_type(),sanitize_text_field($target['canonical_id']??''),absint($target['id']??0),$decision['fingerprint'],'imported',$now,$now,$now));EduFlow_Audit_Service::log('migration_entity_imported',$adapter->entity_type(),$target['id']??0,null,array('source'=>$adapter->key(),'source_id'=>$adapter->source_id($row)),$run['institute_id']);}
	private static function conflict($run,$adapter,$row,$decision){global $wpdb;$now=current_time('mysql',true);$type='invalid'===$decision['decision']?'invalid_data':('Source changed after migration.'===$decision['reason']?'source_changed':('student'===$adapter->entity_type()?'ambiguous_student':('teacher'===$adapter->entity_type()?'ambiguous_teacher':'missing_parent_record')));$wpdb->insert(EduFlow_DB::table('migration_conflicts'),array('institute_id'=>$run['institute_id'],'run_id'=>$run['id'],'source_key'=>$adapter->key(),'source_table'=>$adapter->source_table(),'source_id'=>$adapter->source_id($row),'entity_type'=>$adapter->entity_type(),'conflict_type'=>$type,'source_fingerprint'=>$decision['fingerprint']??null,'source_summary'=>wp_json_encode(self::redact($decision['normalized']??array())),'reason'=>sanitize_textarea_field($decision['reason']),'conflict_status'=>'open','status'=>'active','created_at'=>$now,'updated_at'=>$now));if($wpdb->insert_id){EduFlow_Audit_Service::log('migration_conflict_created','migration_conflict',$wpdb->insert_id,null,array('type'=>$type,'source'=>$adapter->key()),$run['institute_id']);}}
	private static function redact($data){foreach(array('password','pass','token','secret','refresh_token','access_token')as$key){unset($data[$key]);}return $data;}
	private static function fail_run($run,$error){global $wpdb;$wpdb->update(EduFlow_DB::table('migration_runs'),array('run_status'=>'failed','last_error'=>sanitize_textarea_field($error),'updated_at'=>current_time('mysql',true)),array('id'=>$run['id'],'institute_id'=>$run['institute_id']));}
	public static function resume($run_id){global $wpdb;$run=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".EduFlow_DB::table('migration_runs')." WHERE id=%d AND institute_id=%d AND run_status='failed'",$run_id,EduFlow_Settings::institute_db_id()),ARRAY_A);if(!$run){return new WP_Error('run_not_resumable','Migration run is not resumable.');}$wpdb->update(EduFlow_DB::table('migration_runs'),array('run_status'=>'pending','last_error'=>null,'updated_at'=>current_time('mysql',true)),array('id'=>$run_id,'institute_id'=>$run['institute_id']));EduFlow_Audit_Service::log('migration_resumed','migration_run',$run_id,null,array('cursor'=>$run['cursor_value']),$run['institute_id']);return self::queue($run_id,$run['cursor_value']);}
	public static function resolve($conflict_id,$resolution,$target_id=0){global $wpdb;$allowed=array('link_existing','create_new','skip','keep_eduflow','use_legacy','manual');$resolution=sanitize_key($resolution);if(!in_array($resolution,$allowed,true)){return new WP_Error('invalid_resolution','Invalid conflict resolution.');}$institute=EduFlow_Settings::institute_db_id();$result=$wpdb->update(EduFlow_DB::table('migration_conflicts'),array('resolution'=>$resolution,'resolved_target_id'=>$target_id?:null,'resolved_by'=>get_current_user_id(),'resolved_at'=>current_time('mysql',true),'conflict_status'=>'resolved','updated_at'=>current_time('mysql',true)),array('id'=>$conflict_id,'institute_id'=>$institute,'conflict_status'=>'open'));if($result){EduFlow_Audit_Service::log('migration_conflict_resolved','migration_conflict',$conflict_id,null,array('resolution'=>$resolution,'target_id'=>$target_id),$institute);}return $result;}
	public static function readiness($institute_id=0){global $wpdb;$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();$runs=EduFlow_DB::table('migration_runs');$conflicts=EduFlow_DB::table('migration_conflicts');$map=EduFlow_DB::table('migration_map');$failed=(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(failed_count),0) FROM $runs WHERE institute_id=%d AND status='active'",$institute_id));$open=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $conflicts WHERE institute_id=%d AND conflict_status='open'",$institute_id));$completed=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $runs WHERE institute_id=%d AND run_status='completed' AND mode<>'dry_run'",$institute_id));$entities=array('student','teacher','admission','payment','access','batch','class','demo_session','demo_booking','meet');$reconciled=array();foreach($entities as$entity){$reconciled[$entity]=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $map WHERE institute_id=%d AND new_entity=%s AND migration_status='imported'",$institute_id,$entity));}$overall=$open||$failed?'REVIEW REQUIRED':($completed?'READY FOR CONTROLLED CUTOVER':'NOT READY');return array('overall'=>$overall,'conflicts_remaining'=>$open,'failed_records'=>$failed,'completed_import_runs'=>$completed,'reconciled'=>$reconciled,'legacy_plugins_deactivated'=>false);}
}
